import {levelUpRegion,levelUpFieldView} from './levelup-field.js';
import {overrideRegion,overrideFieldView,selectOverrideRegion} from './override-field.js';
import {startControl} from './control.js';
import { startDisplay } from './displays.js';
import { capacity, timeSeconds, clock, balancedEnd, planStats, escapeHtml as h } from './planner.js';
const invoke=window.__TAURI__?.core.invoke;
const api=(action,payload={})=>invoke('dispatch',{action,payload});
const $=s=>document.querySelector(s), root=$('#app'), modal=$('#modal');
const clone=x=>structuredClone(x);
let displayDraft=null,unlockTarget='wizard',overrideSelected='red_quad_1';
let boot,state,event,tab='Matches',welcome=true,wizard=null,step=0,editing=false,password='',confirmation='',plan=null,planError='',planSeq=0,matchDraft=null,skillDraft=null,selected=null,filter='',busy=false,toastTimer,displayMode=false;
const tabs=['Matches','Teams','Skills','Eliminations','Awards','Displays','Reports','Setup'];
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const field=(label,content,help='')=>`<div class="field"><label>${label}</label>${content}${help?`<div class="help">${help}</div>`:''}</div>`;
const input=(path,value,type='text',extra='')=>`<input data-bind="${path}" type="${type}" value="${h(value)}" ${extra}>`;
const check=(path,value,label)=>`<label class="check"><input data-bind="${path}" type="checkbox" ${value?'checked':''}>${label}</label>`;
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const options=(items,value)=>items.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${h(v)}" ${String(v)===String(value)?'selected':''}>${h(l)}</option>`;}).join('');
const select=(path,value,items)=>`<select data-bind="${path}">${options(items,value)}</select>`;
const game=()=>boot.games.find(g=>g.id===(wizard||event).game);
const teamLabel=id=>{const t=event.teams.find(t=>t.id===id);return t?`${t.number}${t.name?' · '+t.name:''}`:'—';};
const teamName=id=>event.teams.find(t=>t.id===id)?.number||'—';
const matchLabel=m=>`${m.round===1?'P':m.round===2?'Q':m.round===15?'F':'E'}${m.number}`;
const teamLine=m=>m.alliances.map(a=>a.teams.map(t=>`${h(teamLabel(t.team))}${t.surrogate?'*':''}`).join(' / ')).join(' <span class="muted">vs</span> ');
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast')?.classList.remove('show'),6500);}
function assign(path,value){let o=wizard||event;const a=path.split('.');while(a.length>1)o=o[a.shift()];o[a[0]]=value;}
function accept(s){state=s;event=s.event;}
function closeModal(){modal.close();modal.innerHTML='';modal.classList.remove('display-editor');}
function dialog(html){modal.innerHTML=html;modal.showModal();}
function confirmAction(title,description,action){dialog(`<h2>${h(title)}</h2><p>${h(description)}</p><div class="actions">${btn('Cancel','close-modal')}${btn('Continue',action,'primary')}</div>`);}
let matchListScroll=0,lastCenteredMatch=null;
function restoreMatchPosition(){
 const list=$('#match-list');if(!list)return;
 list.scrollTop=matchListScroll;list.querySelectorAll('[data-match-id]').forEach(el=>el.classList.toggle('on-field',+el.dataset.matchId===state.active));
 if(state.active!==lastCenteredMatch){const card=list.querySelector(`[data-match-id="${state.active}"]`);if(card){list.scrollTop=card.offsetTop-list.offsetTop-list.clientHeight/2+card.offsetHeight/2;matchListScroll=list.scrollTop;}lastCenteredMatch=state.active;}
 list.addEventListener('scroll',()=>{matchListScroll=list.scrollTop;},{passive:true});
}
function shell(content){const old=$('#match-list');if(old)matchListScroll=old.scrollTop;root.innerHTML=`<div class="manager-shell ${tab==='Matches'?'matches-shell':''}"><nav class="app-nav">${(window.__TM_REMOTE__?['Matches','TM']:tabs).map(t=>btn(t,`tab:${t}`,tab===t?'active ghost':'ghost')).join('')}${window.__TM_REMOTE__?'':`<div class="grow"></div>${btn('Field Control ↗','field-control','tab-field-control')}`}</nav><main class="workspace">${state.error?`<div class="notice error">${h(state.error)}</div>`:''}${content}</main></div>`;restoreMatchPosition();}
function render(){if(displayMode)return;if(wizard){renderWizard();return;}if(welcome){root.innerHTML=`<main class="welcome"><div class="eyebrow">2026 / 2027 season</div><h1>Tournament Manager</h1>${btn('Create a new tournament','new','choice')}${btn('Open an existing tournament','open','choice')}${btn('Connect to a remote tournament','connect-remote','choice')}<div class="row" style="margin-top:25px">${btn('Try a VEX V5 demo','demo:v5','ghost')}${btn('Try a VEX IQ demo','demo:iq','ghost')}</div></main>`;return;}shell(pages[tab]());}
const pages={
 Teams:()=>`<div class="row between"><h1>Teams</h1>${btn('Edit roster in setup','edit-setup')}</div><div class="card"><input id="team-search" placeholder="Search team number, name, or organization" value="${h(filter)}"></div><div class="table-wrap"><table><thead><tr><th>Number<th>Team name<th>Organization<th>Age group<th>Checked in<th>Inspected</tr></thead><tbody>${event.teams.filter(t=>`${t.number} ${t.name} ${t.organization}`.toLowerCase().includes(filter.toLowerCase())).map(t=>`<tr><td><b>${h(t.number)}</b><td>${h(t.name)}<td>${h(t.organization)}<td>${h(t.age_group)}<td><input type="checkbox" data-team="${t.id}" data-prop="checked_in" ${t.checked_in?'checked':''}><td><input type="checkbox" data-team="${t.id}" data-prop="inspected" ${t.inspected?'checked':''}></tr>`).join('')}</tbody></table></div>`,
 Matches:()=>matchesPage(),
 Rankings:()=>`<h1>Qualification rankings</h1>${rankTable(state.rankings)}`,
 Skills:()=>skillsPage(),
 Eliminations:()=>elimsPage(),
 Awards:()=>`<div class="row between"><h1>Awards</h1>${btn('Add award','add-award')}</div><div class="card">${event.awards.map((a,i)=>`<div class="form-grid" style="margin-bottom:20px">${field('Award',input(`awards.${i}.name`,a.name))}${field('Winning team',select(`awards.${i}.team`,a.team,[[0,'Not assigned'],...event.teams.map(t=>[t.id,`${t.number} · ${t.name}`])]))}</div>`).join('')||'<p>No awards selected.</p>'}${btn('Save award assignments','save-awards','primary')}</div>`,
 Displays:()=>`<div class="row between"><h1>Displays</h1>${btn('Edit displays & logos','edit-displays','primary')}</div><div class="grid">${event.config.displays.map(d=>`<div class="card"><span class="pill">${h(d.kind)}</span><h2 style="margin-top:15px">${h(d.name)}</h2><p class="muted">${h(d.kind==='Field'?d.field:d.screen)} ${d.fullscreen?'· Full screen':''}</p>${d.kind==='Pit'?`<label>Rankings screen<select data-pit-screen="${d.id}">${options([['Rankings','Qualification rankings'],['Skills','Skills rankings']],d.screen)}</select></label>`:''}${btn('Open display',`display:${d.id}`,'primary')}</div>`).join('')}</div><div class="card"><h2>Sponsor logos</h2><div class="row">${event.config.sponsors.map(s=>`<img class="sponsor-thumb" src="${imageUrl(s)}" alt="${h(s.name)}">`).join('')}</div>${btn('Edit displays and sponsor logos','edit-displays','primary')}</div><div class="card"><h2>Announcement</h2><textarea id="announcement">${h(event.announcements)}</textarea></div>`,
 Reports:()=>`<h1>Reports</h1><div class="grid">${[['time','Schedule by time'],['team','Schedule by team'],['teams','Team list'],['rankings','Final qualification rankings'],['skills','Skills rankings'],['bracket','Elimination bracket / finals'],['results','Match results'],['awards','Awards']].map(([id,label])=>`<div class="card"><h2>${label}</h2>${btn('Export PDF…',`pdf:${id}`,'primary')}</div>`).join('')}</div><div class="card"><h2>Data exports</h2><div class="row">${btn('Export team CSV…','export:teams')}${btn('Export event JSON…','export:event')}${btn('Schedule HTML…','report:time')}</div></div>`,
 Setup:()=>`<h1>Tournament setup</h1>${btn('Connect to a remote tournament','connect-remote')}<div class="card"><h2>Event server</h2><p>Start the event server, then open <b>http://this-computer-ip:8790</b> on another computer. Enter the tournament network password, then choose a display.</p><p>For password-protected match control and score entry, open <b>http://localhost:8790/TM</b> on this computer, or replace localhost with this computer’s IP address.</p>${btn(state.server?'Server running on port 8790':'Start event server','server','primary')}</div><div class="card"><h2>Event configuration</h2><div class="row">${btn('New tournament','new')}${btn('Open tournament…','open')}${btn('Save','save')}</div>${btn('Open setup walkthrough','edit-setup','primary')}</div><div class="card"><h2>Field hardware</h2>${state.platform==='windows'?`<div class="row">${btn('Install CP210x USB driver…','install-driver:cp210x')}${btn('Install legacy x86 runtime…','install-driver:msvc')}</div><p class="muted">Bundled CP210x 6.6 is a legacy driver for Windows XP–8. Install only when needed; newer Windows versions may already have a newer driver.</p>`:''}<p class="muted">Uses the bundled V5 controller driver.</p>${field('V5 driver',`<input id="driver-path" value="${h(state.hardware.driver||'')}">`)}<div class="row">${btn('Discover controllers','hardware:discover')}${btn('Rescan','hardware:rescan')}${btn('USB diagnostics','hardware-diagnostics')}<label>Device index</label><input id="device-index" type="number" min="0" value="0">${btn('Connect','hardware:connect','primary')}${btn('Disable & disconnect','hardware:disconnect','danger')}</div><div class="notice">${state.hardware.connected?'Connected':'Disconnected'} · ${state.hardware.count} controller(s) discovered</div><div class="notice ${state.hardware.count?'':'warn'}">${h(state.hardware.usb?.message||'If no controller is found, run USB diagnostics to check whether macOS sees the Brain.')}</div><pre style="white-space:pre-wrap;font-size:15px">${h(JSON.stringify({controller:state.hardware.status,usb:state.hardware.usb?.devices},null,2))}</pre></div>`
};
function rankTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Rank<th>Team<th>Name<th>${game()?.cooperative?'Average':'WP'}<th>AP<th>SP<th>W–L–T<th>Played</tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}<td><b>${h(teamName(r.team))}</b><td>${h(event.teams.find(t=>t.id===r.team)?.name||'')}<td>${(game()?.cooperative?r.average_score:r.wp).toFixed(2)}<td>${r.ap.toFixed(2)}<td>${r.sp.toFixed(2)}<td>${r.wins}–${r.losses}–${r.ties}<td>${r.played}</tr>`).join('')}</tbody></table></div>`;}
function matchesPage(){const m=matchDraft||event.matches.find(m=>m.id===selected);return `<h1>Matches</h1><div class="matches-layout"><div id="match-list" class="match-list">${event.matches.map(m=>`<div class="match-card ${m.id===selected?'active':''}" data-action="match:${m.id}" data-match-id="${m.id}"><div class="row between"><b>${matchLabel(m)}</b><span class="pill ${m.state==='Submitted'?'green':'gray'}">${m.state}</span></div><p style="font-size:14px;margin:6px 0">${m.alliances.map(a=>a.teams.map(t=>h(teamName(t.team))).join(' / ')).join(' vs ')}</p><div class="meta">${h(m.field)} · ${h(m.planned)}</div>${m.state!=='Submitted'?btn('Send to FC',`send-fc:${m.id}`,'small',state.active===m.id?'disabled':''):''}</div>`).join('')}</div><div class="match-editor">${m?`<div class="card"><div class="row between"><h2>${matchLabel(m)} · ${h(m.field)}</h2><span>${teamLine(m)}</span></div><div id="score-result"></div>${m.state==='Submitted'?`<div class="row between"><span class="pill">Locked</span>${btn('Unlock match',`unlock-match:${m.id}`)}</div>`:scoreControls(m,false)}<div class="row" style="margin-top:22px">${btn('Save score draft','score-draft','',m.state==='Submitted'?'disabled':'')}${btn('Submit final score','score-submit','primary',m.state==='Submitted'?'disabled':'')}</div></div>`:'<div class="empty">Choose a match to score or run.</div>'}</div></div>`;}
function timerPanel(){return `<div class="card"><div class="row between"><h2>Field control</h2><span class="pill ${state.hardware.connected?'green':'gray'}">${state.hardware.connected?'Controller connected':'No controller connected'}</span></div><div class="row"><div id="clock" class="timer">${clock(state.timer.seconds)}</div><div id="phase" class="muted">${h(state.timer.phase)}</div></div><div class="row" style="margin-top:15px">${btn('Start','timer:start','primary')}${btn('Pause','timer:pause')}${btn('Resume / Driver','timer:resume')}${btn('Abort & disable','timer:abort','danger')}${btn('Reset','timer:reset')}</div></div>`;}
function scoreControls(m,skills){
 const groups=[[],[],[]],iq=game().cooperative,override=game().id==='VRC_2026_Override',levelup=game().id==='VIQC_2026_LevelUp',regions={};
 for(const c of (skills?game().skills_controls:game().controls)){
 const raw=c.name.replace(/^skills_/,''),ai=raw.startsWith('a1_')?0:raw.startsWith('a2_')?1:-1,key=ai>=0?raw.slice(3):raw,v=ai>=0?(m.alliances[ai]?.values[key]??c.default):(m.values[key]??c.default),attrs=`data-score="${h(key)}" data-alliance="${ai}"`;
 const number=`<input type="number" ${attrs} value="${v}" min="${c.min}" max="${c.max}" inputmode="numeric" aria-label="${h(c.label)}">`;
 const control=c.kind==='wxCheckBox'?`<input type="checkbox" ${attrs} ${v?'checked':''}>`:c.choices.length?`<select ${attrs}>${options(c.choices.map((x,i)=>[i,x]),v)}</select>`:window.__TM_REMOTE__?`<div class="score-stepper">${[-5,-1].map(n=>`<button type="button" data-score-step="${n}" aria-label="Subtract ${-n}">${n===-1?'−':'−5'}</button>`).join('')}${number}${[1,5].map(n=>`<button type="button" data-score-step="${n}" aria-label="Add ${n}">+${n}</button>`).join('')}</div>`:number;
 const region=override?overrideRegion(key):null;
 const label=region?key.slice(region.id.length+1).replaceAll('_',' ').replace('toggle','Toggle ownership'):c.label.replace(/^skills[ _]/,'').replace(/^a[12][ _]/,'').replaceAll('_',' ');
 const coloredLabel=h(label).replace(/\b(red|blue|yellow) pins\b/gi,(text,color)=>`<span class="pin-label pin-${color.toLowerCase()}">${text}</span>`);
 const html=`<div class="score-control"><label>${coloredLabel}</label>${control}</div>`;
 const iqRegion=levelup?levelUpRegion(key):null;
 if(iqRegion)(regions[iqRegion]??=[]).push(html);else if(region)(regions[region.id]??=[]).push(html);else groups[ai+1].push(html);
 }
 const dq=ai=>!skills?(m.alliances[ai]?.teams||[]).map((t,ti)=>`<div class="row"><label class="check"><input type="checkbox" data-dq="${ai},${ti}" ${t.dq?'checked':''}>${h(teamName(t.team))} DQ</label><label class="check"><input type="checkbox" data-noshow="${ai},${ti}" ${t.no_show?'checked':''}>No show</label></div>`).join(''):'';
 return `${override?overrideFieldView(regions,overrideSelected):levelup?levelUpFieldView(regions):''}<div class="alliance-score-layout">${[0,1].filter(ai=>groups[ai+1].length||m.alliances[ai]).map(ai=>`<section class="alliance-score ${!skills&&!iq?(ai?'score-blue':'score-red'):'score-neutral'}"><h3>${skills?'Skills':iq?'Teamwork':ai?'Blue alliance':'Red alliance'}</h3><div class="score-grid">${groups[ai+1].join('')}</div>${dq(ai)}</section>`).join('')}</div>${groups[0].length?`<section class="alliance-score score-shared"><h3>Match details</h3><div class="score-grid">${groups[0].join('')}</div></section>`:''}`;
}
function skillsPage(){return `<h1>Robot Skills Challenge</h1><div class="card"><div class="row"><select id="skill-team" style="width:280px">${options(event.teams.map(t=>[t.id,`${t.number} · ${t.name}`]),skillDraft?.alliances[0].teams[0].team||event.teams[0]?.id)}</select><select id="skill-type" style="width:250px">${options([[0,'Driving Skills'],[1,'Autonomous Coding']],skillDraft?.programming?1:0)}</select>${btn('New attempt','skill-new','primary')}</div></div>${skillDraft?`<div class="card"><h2>Score attempt</h2><div id="skill-result"></div>${scoreControls(skillDraft,true)}<div class="row" style="margin-top:20px">${btn('Record attempt','skill-record','primary')}${btn('Cancel','skill-cancel')}</div></div>`:''}<div class="table-wrap"><table><thead><tr><th>Team<th>Challenge<th>Attempt<th>Score<th>Stop time</tr></thead><tbody>${event.skills.map(s=>`<tr><td>${h(teamName(s.team))}<td>${s.programming?'Autonomous Coding':'Driving'}<td>${s.attempt}<td>${s.score}<td>${s.stop_time}</tr>`).join('')}</tbody></table></div>`;}
function elimsPage(){
 const iq=game()?.cooperative,started=event.bracket.length||event.matches.some(m=>m.round>2),used=new Set(event.alliances.flat()),available=state.rankings.filter(r=>!used.has(r.team)),captain=available[0],limit=Math.min(event.config.elimination_alliances,Math.floor(event.teams.length/2));
 return `<h1>${iq?'Teamwork finals':'Eliminations'}</h1>${started?`<div class="card">${event.matches.filter(m=>m.round>2).map(m=>`<div class="match-card" data-action="match:${m.id}"><b>${matchLabel(m)}</b> · ${teamLine(m)} · ${m.state}</div>`).join('')}${btn('Remove eliminations','unlock-elims','danger')}</div>`:iq?`<div class="card">${btn('Create Teamwork finals','create-elims','primary')}</div>`:`<div class="card"><h2>Alliance selection</h2>${event.alliances.length?btn('Undo last selection','selection-undo','ghost'):''}${event.alliances.map((a,i)=>`<div class="match-card"><b>Seed ${i+1}</b> · ${a.map(id=>h(teamLabel(id))).join(' / ')}</div>`).join('')}${!event.selection_started?btn('Start alliance selection','selection-start','primary'):event.alliances.length<limit&&captain?`<h3>Seed ${event.alliances.length+1} captain: ${h(teamLabel(captain.team))}</h3><div class="row">${available.slice(1).map(r=>btn(`${h(teamName(r.team))} · ${h(event.teams.find(t=>t.id===r.team)?.name||'')}`,`selection-pick:${r.team}`)).join('')}</div>`:btn('Create elimination bracket','create-elims','primary',event.alliances.length<2?'disabled':'')}</div>`}`;
}
function imageUrl(s){const bytes=new Uint8Array(s.image);let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return `data:${bytes[0]===137?'image/png':'image/jpeg'};base64,${btoa(str)}`;}
const descriptions=[
 'Choose the robotics program for this tournament.',
 'Choose a starting configuration. You can review every setting in this walkthrough.',
 'Name your event and secure connections from other computers.',
 'This proof of concept includes the latest recovered season for each supported program.',
 'Import a CSV roster, generate numbered teams, or add teams individually.',
 'Set the size and format of the final tournament.',
 'Name the competition fields available for matches.',
 'Choose the skills challenges available to your teams.',
 'Create logical pit, field, and audience displays.',
 'Build your event day, check capacity, and leave time for breaks.',
 'Generate and review practice and qualification matches separately.',
 'Select the awards to present at the end of your event.'
];
function renderWizard(){root.innerHTML=`<div class="wizard"><aside class="wizard-aside"><div class="brand">Tournament<br>Setup</div>${boot.steps.map((s,i)=>`<div class="step ${step===i?'current':i<step?'done':''}"><b>${i<step?'✓':i+1}</b>${h(s)}</div>`).join('')}</aside><section class="wizard-main"><header class="wizard-top"><div class="eyebrow">${editing?'Edit tournament':'Create tournament'} · Step ${step+1} of 12</div><h1>${boot.steps[step]}</h1></header><div class="wizard-body">${wizardPage()}<div id="wizard-error" class="notice error" hidden></div></div><footer class="wizard-footer">${btn('Cancel','wizard-cancel','ghost')}<div class="grow"></div>${btn('Back','wizard-back','',step===0?'disabled':'')}${btn(step===11?(editing?'Save changes':'Create tournament'):'Next','wizard-next','primary',busy?'disabled':'')}</footer></section></div>`;if(step===9)refreshPlan();}
function wizardPage(){const e=wizard,c=e.config;switch(step){
 case 0:return `<div class="grid">${[['VEX IQ','VIQC_2026_LevelUp','iq.png','Cooperative Teamwork Challenge'],['VEX V5','VRC_2026_Override','v5.png','Two alliances. Two teams per alliance.']].map(([name,id,img,desc])=>`<button class="program ${e.game===id?'selected':''}" data-action="program:${id}"><img src="${img}" alt="${name}"><h2>${name}</h2></button>`).join('')}</div>`;
 case 1:return boot.presets.map((p,i)=>`<button class="preset ${c.tournament_type===p?'selected':''}" data-action="preset:${i}">${p}<small>${['A small unofficial event, with simple defaults and a generated roster.','One competition field with a straightforward event schedule.','Two competition fields, with time to review settings.','Multiple fields and complete control over event configuration.'][i]}</small></button>`).join('');
 case 2:return `<div class="card">${field('Event name',input('name',e.name),'Used on printed reports, audience displays, and pit displays.')}<div class="form-grid">${field('Event date',input('date',e.date||today(),'date'))}${field('Venue',input('venue',e.venue))}</div></div><div class="card"><h2>Tournament network password</h2><p class="muted">Other computers use this password to connect to your server. You will not need it when reopening this tournament locally.</p><div class="form-grid">${field(editing?'New password (leave blank to keep current)':'Network password',`<input id="password" type="password" autocomplete="new-password" value="${h(password)}">`)}${field('Confirm password',`<input id="confirmation" type="password" autocomplete="new-password" value="${h(confirmation)}">`)}</div>${btn('Create random password','random-password')}${check('config.protect_options',c.protect_options,'Require this password when opening tournament options')}</div>`;
 case 3:return `<div class="card"><span class="pill">${h(game().season||'2026 / 2027')}</span><h2 style="margin-top:20px">${h(game().title)}</h2></div>`;
 case 4:return `<div class="row between" style="margin-bottom:20px"><span class="pill">${e.teams.length} teams</span><div class="row">${btn('Import CSV…','wizard-import')}${btn('Import original TM…','wizard-import-original','ghost')}${btn('Generate teams…','generate-teams')}${btn('Add team','add-team')}${btn('Clear','clear-teams','danger')}</div></div><div class="table-wrap"><table><thead><tr><th>Number<th>Age group<th>Team name<th>Organization<th></tr></thead><tbody>${e.teams.map((t,i)=>`<tr><td>${input(`teams.${i}.number`,t.number)}<td>${input(`teams.${i}.age_group`,t.age_group)}<td>${input(`teams.${i}.name`,t.name)}<td>${input(`teams.${i}.organization`,t.organization)}<td>${btn('Remove',`remove-team:${i}`,'small ghost')}</tr>`).join('')}</tbody></table></div>${!e.teams.length?'<div class="empty">Add your team list to continue.</div>':''}<p class="help">CSV columns: Number, Age Group, Team Name, Organization, City.</p>`;
 case 5:return game().cooperative?`<div class="card">${field('Teams advancing to Teamwork finals',input('config.iq_finalists',c.iq_finalists,'number','min="2" step="2"'))}<p class="help">Choose an even number. Teams are paired from the qualification rankings.</p></div>`:`<div class="card"><div class="form-grid">${field('Elimination alliances',input('config.elimination_alliances',c.elimination_alliances,'number','min="2" max="32"'))}${field('Wins to take a series',select('elimination_wins',e.elimination_wins,[[1,'One win'],[2,'Two wins']]))}</div><div class="notice">Matches are strictly 2v2. Each elimination alliance contains exactly two teams.</div>${field('Alliance selection display order',select('config.selection_order',c.selection_order,['Ranking','Team number']))}</div>`;
 case 6:return `<div class="card"><h2>Competition fields</h2>${c.field_sets.map((f,i)=>`${field('Field set name',input(`config.field_sets.${i}.name`,f.name))}${f.fields.map((name,j)=>`<div class="row" style="margin:12px 0"><input data-bind="config.field_sets.${i}.fields.${j}" value="${h(name)}">${btn('Remove',`remove-field:${i},${j}`,'ghost')}</div>`).join('')}`).join('')}<div class="row">${btn('Add field','add-field')}</div><div class="notice">Schedule capacity uses all competition fields simultaneously. If your field set alternates matches, configure one scheduling field for now.</div></div>`;
 case 7:return `<div class="card">${check('config.skills_driver',c.skills_driver,'Driving Skills')}${check('config.skills_autonomous',c.skills_autonomous,'Autonomous Coding Skills')}<div class="form-grid">${field('Skills fields',input('config.skills_fields',c.skills_fields,'number','min="1" max="20"'))}${field('Maximum attempts per team, per challenge',input('config.skills_max_attempts',c.skills_max_attempts,'number','min="1" max="10"'))}</div></div>`;
 case 8:return `<div class="card"><div class="row between"><h2>Logical displays</h2>${btn('Add display','add-display')}</div>${c.displays.map((d,i)=>`<div class="form-grid" style="margin:20px 0;border-top:1px solid var(--line);padding-top:20px">${field('Display name',input(`config.displays.${i}.name`,d.name))}${field('Type',select(`config.displays.${i}.kind`,d.kind,['Pit','Field','Audience']))}${field(d.kind==='Field'?'Field':'Default screen',d.kind==='Field'?select(`config.displays.${i}.field`,d.field,c.field_sets.flatMap(f=>f.fields)):select(`config.displays.${i}.screen`,d.screen,['Rankings','Skills']))}<div>${check(`config.displays.${i}.fullscreen`,d.fullscreen,'Full screen')}${btn('Remove',`remove-display:${i}`,'small ghost')}</div></div>`).join('')}</div><div class="card"><div class="row between"><h2>Sponsor logos</h2>${btn('Add logo…','wizard-sponsor')}</div><div class="row">${c.sponsors.map((s,i)=>`<div><img class="sponsor-thumb" src="${imageUrl(s)}" alt="${h(s.name)}">${btn('Remove',`remove-sponsor:${i}`,'small ghost')}</div>`).join('')}</div></div>`;
 case 9:return schedulePage();
 case 10:return generationPage();
 case 11:return `<div class="card"><h2>Event awards</h2>${boot.awards.filter(a=>game().cooperative?!a.startsWith('Tournament'):!a.startsWith('Teamwork')).map(name=>`<label class="check"><input type="checkbox" data-award="${h(name)}" ${e.awards.some(a=>a.name===name)?'checked':''}>${h(name)}</label>`).join('')}</div><div class="notice">Your tournament is ready. You can assign award winners and open displays after creation.</div>`;
}}
function schedulePage(){const e=wizard,stats=planStats(e,game().team_size*2);const blocks=e.config.schedule.blocks.map((b,i)=>({...b,index:i})).sort((a,b)=>`${a.date} ${a.start}`.localeCompare(`${b.date} ${b.start}`));let last='';return `<div class="row between" style="margin-bottom:20px"><div class="row"><span class="pill">${e.teams.length} teams</span><span class="pill gray">${stats.fields} field${stats.fields===1?'':'s'}</span></div><div class="row">${btn('Build a day plan…','day-template')}${btn('+ Add time block','add-block','primary')}</div></div><div class="schedule-layout"><section>${blocks.length?blocks.map(b=>{const date=b.date!==last?`<div class="timeline-date">${h(b.date)}</div>`:'';last=b.date;return `${date}<article class="block ${b.round===1?'practice':'qualification'}"><div class="block-time">${h(b.start)}–${h(b.end)}<small>${Math.max(0,(timeSeconds(b.end)-timeSeconds(b.start))/60)} minutes</small></div><div><h3>${b.round===1?'Practice':'Qualifications'}</h3><div class="meta">${capacity(b,stats.fields)} matches · ${(capacity(b,stats.fields)*game().team_size*2/e.teams.length).toFixed(2)} appearances/team<br>${Math.floor(b.cycle_seconds/60)} min ${b.cycle_seconds%60?`${b.cycle_seconds%60} sec `:''}cycle · ${stats.fields} field${stats.fields===1?'':'s'}</div></div><div class="block-actions">${btn('Edit',`edit-block:${b.index}`,'small')}${btn('Duplicate',`duplicate-block:${b.index}`,'small ghost')}${btn('Remove',`remove-block:${b.index}`,'small ghost')}</div></article>`;}).join(''):`<div class="empty"><h2>Start with your event day</h2><p>Add time blocks for practice and qualifications.<br>Gaps between blocks become breaks.</p>${btn('Build a day plan…','day-template','primary')}</div>`}<div class="notice">Cycle time includes the match, field reset, and team changeover. Add separate blocks before and after lunch or other breaks.</div><div id="plan-warnings"></div></section><aside class="schedule-summary"><div class="card"><h2>Schedule capacity</h2><div class="stats"><div class="stat"><span>Practice matches</span><strong>${stats.practice}</strong><span>≈ ${stats.practicePerTeam.toFixed(2)} per team</span></div><div class="stat"><span>Qualification matches</span><strong>${stats.qualifications}</strong><span>≈ ${stats.qualificationPerTeam.toFixed(2)} per team</span></div></div><div id="plan-status" class="help">Checking your schedule…</div><div class="summary-line"><span>Matches run on</span><b>${stats.fields} field${stats.fields===1?'':'s'}</b></div><div class="summary-line"><span>Teams per match</span><b>${game().team_size*2}</b></div><p class="help">Capacity is an estimate. The preview checks actual counted appearances and marks surrogate slots.</p>${btn('Preview team appearances','plan-details','',!blocks.length?'disabled':'')}</div></aside></div>`;}
async function refreshPlan(){const n=++planSeq;try{const p=await api('plan',{event:wizard});if(n!==planSeq||!wizard)return;plan=p;planError='';if($('#plan-status'))$('#plan-status').innerHTML='<span class="pill green">Schedule checked</span>';if($('#plan-warnings'))$('#plan-warnings').innerHTML=p.warnings.map(w=>`<div class="notice warn">${h(w)}</div>`).join('');}catch(e){if(n!==planSeq)return;plan=null;planError=String(e);if($('#plan-status'))$('#plan-status').textContent='Schedule needs attention';if($('#plan-warnings'))$('#plan-warnings').innerHTML=`<div class="notice error">${h(e)}</div>`;}}
function generationPage(){return `<div class="notice">Review the schedule and generate each match type. Existing matches of that type will be replaced.</div><div class="grid">${[[1,'Practice matches'],[2,'Qualification matches']].map(([round,title])=>{const ms=wizard.matches.filter(m=>m.round===round),counts=wizard.teams.map(t=>ms.reduce((n,m)=>n+m.alliances.flatMap(a=>a.teams).filter(s=>s.team===t.id&&!s.surrogate).length,0));const has=wizard.config.schedule.blocks.some(b=>b.round===round);return `<div class="generation"><span class="pill ${ms.length?'green':'gray'}">${ms.length?'Generated':has?'Ready to generate':'No block scheduled'}</span><h2 style="margin-top:20px">${title}</h2><strong>${ms.length}<small> matches</small></strong><p class="muted">${ms.length?`${Math.min(...counts)}–${Math.max(...counts)} counted matches per team`:round===1&&!has?'Practice is optional.':'Generate matches from your configured time blocks.'}</p>${btn(ms.length?'Regenerate matches':'Create matches',`generate:${round}`,'primary',busy||!has?'disabled':'')}${ms.length?btn('View schedule',`preview-matches:${round}`,'ghost'):''}</div>`;}).join('')}</div><div class="card" style="margin-top:22px"><h2>Before continuing</h2><p>Qualification matches must be generated. If you change the game, roster, fields, or schedule, regenerate matches before creating your tournament.</p><div class="row">${busy?'<span class="spinner"></span><span>Balancing partners and opponents…</span>':''}</div></div>`;}
function invalidate(){wizard.matches=[];wizard.bracket=[];wizard.alliances=[];plan=null;}
async function beginNewTournament(){await flushAutosave();const result=await api('new_file');if(!result.created)return false;startWizard();return true;}
function startWizard(isEdit=false){if(['Countdown','Autonomous','Driver','Paused','AutoPause'].includes(state.timer.phase))throw Error('Finish or abort the current match before opening tournament setup');editing=isEdit;wizard=clone(isEdit?event:boot.default_event);if(!isEdit){wizard.name='';wizard.date=today();}step=0;password='';confirmation='';plan=null;planError='';render();}
function blockDialog(index=null){const b=index===null?{date:wizard.date||today(),start:'09:00',end:'10:00',round:2,cycle_seconds:360}:wizard.config.schedule.blocks[index];dialog(`<h2>${index===null?'Add time block':'Edit time block'}</h2><form id="block-form" data-index="${index??''}"><div class="form-grid">${field('Match type',`<select name="round">${options([[1,'Practice'],[2,'Qualifications']],b.round)}</select>`)}${field('Date',`<input name="date" type="date" value="${h(b.date)}" required>`)}${field('Start time',`<input name="start" type="time" value="${h(b.start)}" required>`)}${field('End time',`<input name="end" type="time" value="${h(b.end)}" required>`)}${field('Cycle minutes',`<input name="minutes" type="number" min="0" max="60" value="${Math.floor(b.cycle_seconds/60)}" required>`)}${field('Cycle seconds',`<input name="seconds" type="number" min="0" max="59" value="${b.cycle_seconds%60}" required>`)}</div><div class="notice" id="block-estimate"></div><div class="row"><label>Set duration for</label><input id="target-rounds" type="number" min="1" max="100" value="4"><span>matches/team</span>${btn('Fit duration','fit-duration','small')}</div><p class="help">Fit duration reserves enough cycles for complete rounds. Multi-field rounding may add spare capacity; the preview checks actual appearances.</p><div id="block-error" class="notice error" hidden></div><div class="actions">${btn('Cancel','close-modal')}<button class="primary" type="submit">${index===null?'Add block':'Save block'}</button></div></form>`);updateBlockEstimate();}
function readBlock(){const f=$('#block-form');return {date:f.date.value,start:f.start.value,end:f.end.value,round:+f.round.value,cycle_seconds:+f.minutes.value*60 + +f.seconds.value};}
function updateBlockEstimate(){try{const b=readBlock(),stats=planStats(wizard,game().team_size*2),n=capacity(b,stats.fields);$('#block-estimate').textContent=`${n} matches · ${(n*game().team_size*2/wizard.teams.length).toFixed(2)} appearances per team · ${stats.fields} field(s)`;}catch{}}
function dayTemplate(){dialog(`<h2>Build an event day</h2><form id="day-form"><div class="form-grid">${field('Event date',`<input name="date" type="date" value="${h(wizard.date||today())}" required>`)}${field('Match cycle (minutes)',`<input name="cycle" type="number" min="1" max="60" step="0.5" value="6" required>`)}${field('Practice start',`<input name="practice_start" type="time" value="09:00" required>`)}${field('Practice matches per team',`<input name="practice_rounds" type="number" min="0" max="100" value="1" required>`)}${field('Qualifications start',`<input name="qualification_start" type="time" value="10:00" required>`)}${field('Qualification matches per team',`<input name="qualification_rounds" type="number" min="1" max="100" value="4" required>`)}</div><div class="notice warn">This replaces the current schedule blocks and clears generated matches.</div><div id="day-error" class="notice error" hidden></div><div class="actions">${btn('Cancel','close-modal')}<button class="primary" type="submit">Build day plan</button></div></form>`);}
async function action(a){const [name,arg]=a.split(':');switch(name){
 case 'close-modal':closeModal();displayDraft=null;break;
 case 'install-driver':await api('install_driver',{name:arg});break;
 case 'connect-remote':dialog(`<h2>Connect to a remote tournament</h2>${field('Server address','<input id="remote-address" placeholder="192.168.1.20:8790" autocomplete="url" autofocus>')}<p class="muted">Start the event server on the host computer. Enter its tournament password in the connection window.</p><p id="remote-error" class="error-text" role="alert" hidden></p><div class="actions">${btn('Cancel','close-modal')}${btn('Displays','remote-open:displays')}${btn('Match control & scoring','remote-open:control','primary')}</div>`);break;
 case 'remote-open':{const error=$('#remote-error');try{await api('remote_connect',{address:$('#remote-address').value,displays:arg==='displays'});closeModal();}catch(e){error.hidden=false;error.textContent=String(e);}break;}
 case 'new':if(!welcome&&state.dirty){confirmAction('Create a new tournament?','Unsaved changes in the current tournament will be discarded.','new-confirm');}else await beginNewTournament();break;
 case 'new-confirm':closeModal();await beginNewTournament();break;
 case 'open':if(state.dirty&&!welcome){confirmAction('Open another tournament?','Unsaved changes in the current tournament will be discarded.','open-confirm');break;}case 'open-confirm':closeModal();{const s=await api('open');if(s.path){accept(s);welcome=false;wizard=null;tab='Matches';selected=null;matchDraft=null;if(!event.config.configured)startWizard();else render();}}break;
 case 'save':accept(await api('save'));render();break;
 case 'tab':if(arg==='TM'){await api('field_control');break;}tab=arg;render();if(tab==='Matches'&&matchDraft)updateScore();break;
 case 'demo':if(!await beginNewTournament())break;wizard.game=arg==='iq'?'VIQC_2026_LevelUp':'VRC_2026_Override';wizard.config.competition=arg==='iq'?'VEX IQ':'VEX V5';wizard.name='Robotics Invitational';makeTeams(24);wizard.config.iq_finalists=10;wizard.config.schedule.blocks=[{date:today(),start:'09:00',end:'09:36',cycle_seconds:360,round:1},{date:today(),start:'10:00',end:'12:24',cycle_seconds:360,round:2}];password=confirmation='demo-network-password';wizard=await api('generate',{event:wizard,round:1});wizard=await api('generate',{event:wizard,round:2});accept(await api('commit',{event:wizard,password,new:true}));wizard=null;welcome=false;render();break;
 case 'edit-setup':unlockTarget='wizard';if(state.protected){dialog(`<h2>Unlock tournament options</h2><p>Enter the tournament network password.</p><input id="unlock-password" type="password"><div class="actions">${btn('Cancel','close-modal')}${btn('Unlock','unlock','primary')}</div>`);}else startWizard(true);break;
 case 'unlock':accept(await api('unlock',{password:$('#unlock-password').value}));closeModal();if(unlockTarget==='displays')openDisplayEditor();else startWizard(true);break;
 case 'program':if(wizard.game!==arg){wizard.game=arg;wizard.config.competition=arg.startsWith('VIQC')?'VEX IQ':'VEX V5';invalidate();}render();break;
 case 'preset':wizard=await api('preset',{event:wizard,index:+arg});invalidate();render();break;
 case 'random-password':password=confirmation=Array.from(crypto.getRandomValues(new Uint8Array(14)),n=>'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789'[n%55]).join('');render();toast(`Network password: ${password}`);break;
 case 'wizard-back':if(step>0)step--;render();break;
 case 'wizard-cancel':confirmAction('Cancel tournament setup?','Changes made in this walkthrough will be discarded.','wizard-cancel-confirm');break;
 case 'wizard-cancel-confirm':closeModal();wizard=null;render();break;
 case 'wizard-next':try{if(step===2){if(password!==confirmation)throw Error('The passwords do not match');if(!editing&&!password)throw Error('Set a network password for remote connections');if(!wizard.name.trim())throw Error('Enter an event name');}else await api('validate',{event:wizard,step,password,confirmation});if(step===9){await api('plan',{event:wizard});}if(step===11){accept(await api('commit',{event:wizard,password,new:!editing}));wizard=null;welcome=false;tab='Matches';selected=null;matchDraft=null;toast('Tournament created and saved.');}else step++;render();}catch(e){$('#wizard-error').hidden=false;$('#wizard-error').textContent=e;}break;
 case 'wizard-import':case 'wizard-import-original':{const teams=await api('import_teams',{original:name==='wizard-import-original'});const seen=new Set(wizard.teams.map(t=>t.number.toUpperCase()));for(const t of teams){if(!seen.has(t.number.toUpperCase())){t.id=Math.max(0,...wizard.teams.map(t=>t.id))+1;wizard.teams.push(t);seen.add(t.number.toUpperCase());}}invalidate();render();}break;
 case 'generate-teams':dialog(`<h2>Generate teams</h2><p>Create a numbered practice roster. This replaces the current team list and clears generated matches.</p><form id="teams-form">${field('Number of teams','<input name="count" type="number" min="4" max="500" value="24" required>')}<div class="actions">${btn('Cancel','close-modal')}<button type="submit" class="primary">Generate teams</button></div></form>`);break;
 case 'add-team':wizard.teams.push({id:Math.max(0,...wizard.teams.map(t=>t.id))+1,number:'',age_group:'',name:'',organization:'',city:'',checked_in:false,inspected:false,notes:''});invalidate();render();break;
 case 'remove-team':wizard.teams.splice(+arg,1);invalidate();render();break;
 case 'clear-teams':confirmAction('Clear the team list?','This removes all teams and generated matches from the draft.','clear-teams-confirm');break;
 case 'clear-teams-confirm':wizard.teams=[];invalidate();closeModal();render();break;
 case 'add-field':wizard.config.field_sets[0].fields.push(`Field ${wizard.config.field_sets.flatMap(f=>f.fields).length+1}`);invalidate();render();break;
 case 'remove-field':{const [i,j]=arg.split(',').map(Number);wizard.config.field_sets[i].fields.splice(j,1);invalidate();render();}break;
 case 'add-display':wizard.config.displays.push({id:Math.max(0,...wizard.config.displays.map(d=>d.id))+1,name:'Pit Display',kind:'Pit',field:'',screen:'Rankings',fullscreen:false});render();break;
 case 'remove-display':wizard.config.displays.splice(+arg,1);render();break;
 case 'wizard-sponsor':{const s=await api('sponsor');if(s)wizard.config.sponsors.push(s);render();}break;
 case 'remove-sponsor':wizard.config.sponsors.splice(+arg,1);render();break;
 case 'add-block':blockDialog();break;
 case 'edit-block':blockDialog(+arg);break;
 case 'duplicate-block':{const b=clone(wizard.config.schedule.blocks[+arg]);const duration=timeSeconds(b.end)-timeSeconds(b.start);b.start=b.end;const end=timeSeconds(b.start)+duration;if(end>=86400)throw Error('Duplicate would extend past midnight. Add a block on the next day.');b.end=`${String(Math.floor(end/3600)).padStart(2,'0')}:${String(Math.floor(end/60)%60).padStart(2,'0')}`;const draft=clone(wizard);draft.config.schedule.blocks.push(b);await api('plan',{event:draft});wizard=draft;invalidate();render();}break;
 case 'remove-block':wizard.config.schedule.blocks.splice(+arg,1);invalidate();render();break;
 case 'fit-duration':{try{const b=readBlock(),f=$('#block-form');f.end.value=balancedEnd(b.start,wizard.teams.length,game().team_size*2,planStats(wizard,4).fields,+$('#target-rounds').value,b.cycle_seconds);updateBlockEstimate();}catch(e){$('#block-error').hidden=false;$('#block-error').textContent=e;}}break;
 case 'day-template':dayTemplate();break;
 case 'plan-details':{const p=await api('plan',{event:wizard});dialog(`<h2>Counted matches per team</h2><p class="muted">Surrogate appearances are excluded from these totals.</p><div class="table-wrap" style="max-height:50vh"><table><thead><tr><th>Team<th>Practice<th>Qualifications</tr></thead><tbody>${wizard.teams.map(t=>`<tr><td>${h(t.number)}<td>${p.appearances[t.id]?.[0]||0}<td>${p.appearances[t.id]?.[1]||0}</tr>`).join('')}</tbody></table></div><div class="actions">${btn('Close','close-modal','primary')}</div>`);}break;
 case 'generate':if(wizard.matches.some(m=>m.round===+arg)){confirmAction('Replace existing matches?',`This replaces all ${+arg===1?'practice':'qualification'} matches and scores in this draft.`,`generate-confirm:${arg}`);}else await generateRound(+arg);break;
 case 'generate-confirm':closeModal();await generateRound(+arg);break;
 case 'preview-matches':dialog(`<h2>${+arg===1?'Practice':'Qualification'} schedule</h2><div class="table-wrap" style="max-height:55vh"><table><thead><tr><th>Time<th>Match<th>Field<th>Teams</tr></thead><tbody>${wizard.matches.filter(m=>m.round===+arg).map(m=>`<tr><td>${h(m.planned)}<td>${matchLabel(m)}<td>${h(m.field)}<td>${m.alliances.map(a=>a.teams.map(t=>`${h(wizard.teams.find(x=>x.id===t.team)?.number)}${t.surrogate?'*':''}`).join(' / ')).join(' vs ')}</tr>`).join('')}</tbody></table></div><p class="help">* Surrogate appearance.</p><div class="actions">${btn('Close','close-modal','primary')}</div>`);break;
 case 'match':{const id=+arg,m=event.matches.find(m=>m.id===id);if(!m)return;selected=id;matchDraft=clone(event.matches.find(m=>m.id===id));tab='Matches';render();updateScore();}break;
 case 'unlock-match':confirmAction('Unlock match?', 'The score will become a draft. Later elimination rounds may be removed.',`unlock-match-confirm:${arg}`);break;
 case 'unlock-match-confirm':await flushAutosave();accept(await api('reopen_match',{id:+arg}));closeModal();selected=+arg;matchDraft=clone(event.matches.find(m=>m.id===selected));render();updateScore();break;
 case 'score-draft':case 'score-submit':await flushAutosave();accept(await api('submit',{match:matchDraft,draft:name==='score-draft'}));matchDraft=clone(event.matches.find(m=>m.id===selected));render();updateScore();toast(name==='score-submit'?'Final score submitted':'Score draft saved');break;
 case 'timer':accept(await api('timer',{command:arg}));updateTimer();break;
 case 'hardware-diagnostics':accept(await api('hardware_diagnostics'));render();break;
 case 'hardware':accept(await api('hardware',{command:arg,path:$('#driver-path')?.value,index:+($('#device-index')?.value||0)}));render();break;
 case 'edit-displays':unlockTarget='displays';if(state.protected){dialog(`<h2>Unlock display settings</h2><p>Enter the tournament network password.</p><input id="unlock-password" type="password"><div class="actions">${btn('Cancel','close-modal')}${btn('Unlock','unlock','primary')}</div>`);}else openDisplayEditor();break;
 case 'direct-add-display':displayDraft.displays.push({id:Math.max(0,...displayDraft.displays.map(d=>d.id))+1,name:`Pit Display ${displayDraft.displays.length+1}`,kind:'Pit',screen:'Rankings',field:event.config.field_sets.flatMap(f=>f.fields)[0]||'',fullscreen:false});renderDisplayEditor();break;
 case 'direct-remove-display':displayDraft.displays.splice(+arg,1);renderDisplayEditor();break;
 case 'direct-add-logo':{const logo=await api('sponsor');if(logo)displayDraft.sponsors.push(logo);renderDisplayEditor();}break;
 case 'direct-replace-logo':{const logo=await api('sponsor');if(logo)displayDraft.sponsors[+arg].image=logo.image;renderDisplayEditor();}break;
 case 'direct-remove-logo':displayDraft.sponsors.splice(+arg,1);renderDisplayEditor();break;
 case 'direct-logo-up':case 'direct-logo-down':{const i=+arg,j=i+(name==='direct-logo-up'?-1:1);if(j>=0&&j<displayDraft.sponsors.length)[displayDraft.sponsors[i],displayDraft.sponsors[j]]=[displayDraft.sponsors[j],displayDraft.sponsors[i]];renderDisplayEditor();}break;
 case 'direct-save-displays':try{accept(await api('display_settings',displayDraft));displayDraft=null;closeModal();render();toast('Changes saved.');}catch(e){$('#display-error').hidden=false;$('#display-error').textContent=String(e);}break;
 case 'field-control':await api('field_control');break;
 case 'send-fc':await flushAutosave();accept(await api('send_to_fc',{id:+arg}));await api('field_control');render();break;
 case 'display':await api('display',{id:+arg});break;
 case 'export':await api('export',{kind:arg});break;
 case 'pdf':if(await api('report_pdf',{kind:arg}))toast('PDF export complete');break;
 case 'report':await api('report',{by_team:arg==='team'});break;
 case 'server':await api('server');state.server=true;render();toast('Display server listening on port 8790');break;
 case 'add-award':event.awards.push({name:'New award',team:0,recipient:'',description:''});await queueAutosave('awards',{awards:event.awards});render();break;
 case 'save-announcement':accept(await api('announcements',{text:$('#announcement').value}));toast('Announcement updated');break;
 case 'save-awards':accept(await api('awards',{awards:event.awards}));render();toast('Awards saved');break;
 case 'selection-undo':accept(await api('selection_undo'));render();break;
 case 'selection-start':accept(await api('selection_start'));render();break;
 case 'selection-pick':accept(await api('selection_pick',{team:+arg}));render();break;
 case 'create-elims':accept(await api('eliminations'));render();break;
 case 'unlock-elims':confirmAction('Remove elimination matches?','This removes the bracket and its matches so alliances can be selected again.','unlock-elims-confirm');break;
 case 'unlock-elims-confirm':closeModal();accept(await api('unlock_eliminations'));render();break;
 case 'skill-new':{const team=+$('#skill-team').value,programming=$('#skill-type').value==='1';skillDraft=await api('skill_template',{team});skillDraft.programming=programming;render();updateScore(true);}break;
 case 'skill-cancel':skillDraft=null;render();break;
 case 'skill-record':accept(await api('skill_record',{match:skillDraft,team:skillDraft.alliances[0].teams[0].team,programming:skillDraft.programming}));skillDraft=null;render();break;
}}
function makeTeams(n){wizard.teams=Array.from({length:n},(_,i)=>({id:i+1,number:String(i+1),name:`Team ${i+1}`,age_group:'',organization:'',city:'',checked_in:false,inspected:false,notes:''}));invalidate();}
async function generateRound(round){busy=true;render();try{wizard=await api('generate',{event:wizard,round});toast(`${round===1?'Practice':'Qualification'} matches generated`);}finally{busy=false;render();}}
let autosaveChain=Promise.resolve();
function queueAutosave(action,payload){
 const captured=clone(payload);
 autosaveChain=autosaveChain.then(async()=>{const saved=await api(action,captured);state={...saved,event};}).catch(e=>toast(`Autosave failed: ${e}`));
 return autosaveChain;
}
async function flushAutosave(){await autosaveChain;}

let scoreSeq=0;
async function updateScore(skills=false){const target=$(skills?'#skill-result':'#score-result');const m=skills?skillDraft:matchDraft;if(!target||!m)return;const n=++scoreSeq;try{const v=await api(skills?'skill_score':'score',{match:m,programming:m.programming});if(n!==scoreSeq)return;target.innerHTML=`<div class="row">${(v.score.alliances||[]).slice(0,skills?1:2).map((a,i)=>`<strong class="score-total ${i?'blue':'red'}">${a.score??0}</strong>`).join('<span class="muted"> / </span>')}</div>${Array.isArray(v.errors)&&v.errors.length?`<div class="notice error">${h(v.errors.join(', '))}</div>`:''}`;}catch(e){target.innerHTML=`<div class="notice error">${h(e)}</div>`;}}
function updateTimer(){if($('#clock'))$('#clock').textContent=clock(state.timer.seconds);if($('#phase'))$('#phase').textContent=state.timer.phase;}
document.addEventListener('click',e=>{const region=e.target.closest('[data-override-region]');if(region){e.preventDefault();overrideSelected=region.dataset.overrideRegion;selectOverrideRegion(root,overrideSelected);return;}const step=e.target.closest('[data-score-step]');if(step){const input=step.closest('.score-stepper').querySelector('input');const value=Number(input.value)||0;input.value=String(Math.max(Number(input.min),Math.min(Number(input.max),value+Number(step.dataset.scoreStep))));input.dispatchEvent(new Event('input',{bubbles:true}));return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();action(b.dataset.action).catch(e=>toast(String(e)));});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='password')password=el.value;if(el.id==='confirmation')confirmation=el.value;if(el.id==='team-search'){filter=el.value;const pos=el.selectionStart;render();$('#team-search').focus();$('#team-search').setSelectionRange(pos,pos);}if(el.closest('#block-form'))updateBlockEstimate();if(el.dataset.bind){let value=el.type==='checkbox'?el.checked:el.type==='number'?+el.value:el.value;if(el.dataset.bind.endsWith('.team')||el.dataset.bind==='elimination_wins')value=+value;assign(el.dataset.bind,value);if(wizard&&(/^(teams|game)/.test(el.dataset.bind)||el.dataset.bind.startsWith('config.field_sets')||el.dataset.bind.startsWith('config.schedule')))invalidate();if(wizard&&el.dataset.bind.endsWith('.kind'))render();}if(el.dataset.score){const m=skillDraft&&tab==='Skills'?skillDraft:matchDraft;const ai=+el.dataset.alliance;if(ai>=0&&!m.alliances[ai])return;const vals=ai>=0?m.alliances[ai].values:m.values;vals[el.dataset.score]=el.type==='checkbox'?+el.checked:+el.value;updateScore(tab==='Skills');}if(el.dataset.dq||el.dataset.noshow){const [a,t]=(el.dataset.dq||el.dataset.noshow).split(',').map(Number);matchDraft.alliances[a].teams[t][el.dataset.dq?'dq':'no_show']=el.checked;updateScore();}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.pitScreen){accept(await api('pit_screen',{id:+el.dataset.pitScreen,screen:el.value}));render();}if(el.dataset.team){const t=event.teams.find(t=>t.id===+el.dataset.team);t[el.dataset.prop]=el.checked;accept(await api('teams',{teams:event.teams}));}if(el.dataset.award){if(el.checked)wizard.awards.push({name:el.dataset.award,team:0,recipient:'',description:''});else wizard.awards=wizard.awards.filter(a=>a.name!==el.dataset.award);}}catch(e){toast(String(e));accept(await api('snapshot'));render();}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;try{if(f.id==='teams-form'){makeTeams(+f.count.value);closeModal();render();}if(f.id==='block-form'){const b=readBlock();if(b.cycle_seconds<30)throw Error('Cycle time must be at least 30 seconds');const draft=clone(wizard),i=f.dataset.index;if(i==='')draft.config.schedule.blocks.push(b);else draft.config.schedule.blocks[+i]=b;
 // Allow practice-only drafts while building a plan; final validation requires qualifications.
 const checkDraft=clone(draft);if(!checkDraft.config.schedule.blocks.some(x=>x.round===2)){const x=clone(b);x.date='2099-12-31';x.round=2;checkDraft.config.schedule.blocks.push(x);}await api('plan',{event:checkDraft});wizard=draft;invalidate();closeModal();render();}
 if(f.id==='day-form'){const fields=planStats(wizard,4).fields,slots=game().team_size*2,cycle=Math.round(+f.cycle.value*60),blocks=[];for(const[round,start,rounds]of[[1,f.practice_start.value,+f.practice_rounds.value],[2,f.qualification_start.value,+f.qualification_rounds.value]]){if(rounds>0)blocks.push({date:f.date.value,start,end:balancedEnd(start,wizard.teams.length,slots,fields,rounds,cycle),round,cycle_seconds:cycle});}const draft=clone(wizard);draft.config.schedule.blocks=blocks;await api('plan',{event:draft});wizard=draft;invalidate();closeModal();render();}
 }catch(error){const target=f.querySelector('.error')||$('#toast');target.hidden=false;target.textContent=error;}});
document.addEventListener('keydown',e=>{const region=e.target.closest?.('[data-override-region]');if(region&&(e.key==='Enter'||e.key===' ')){e.preventDefault();overrideSelected=region.dataset.overrideRegion;selectOverrideRegion(root,overrideSelected);return;}if((e.metaKey||e.ctrlKey)&&e.key==='s'&&!wizard){e.preventDefault();action('save').catch(e=>toast(String(e)));}});
async function init(){if(!invoke){root.innerHTML='<main class="welcome"><h1>Open the Tauri application</h1><p>This interface connects to the native Rust tournament engine through Tauri.</p></main>';return;}if(new URLSearchParams(location.search).has('control')){displayMode=true;await startControl(api);return;}const id=new URLSearchParams(location.search).get('display');if(id){displayMode=true;await startDisplay(+id,()=>api('snapshot'));return;}boot=await api('bootstrap');accept(boot.state);if(window.__TM_REMOTE__){welcome=false;tab='Matches';}render();setInterval(async()=>{if(wizard||welcome||modal.open)return;try{const s=await api('snapshot');const oldRevision=state.revision,oldActive=state.active;state=s;if(!['Awards','Teams'].includes(tab))event=s.event;updateTimer();if(tab==='Matches'&&oldActive!==s.active)restoreMatchPosition();if(s.revision!==oldRevision&&!['Awards','Teams','Matches','Skills','Eliminations','Setup'].includes(tab))render();}catch{}},400);}
init().catch(e=>{root.innerHTML=`<main class="welcome"><h1>Unable to start</h1><p>${h(e)}</p></main>`;});

function openDisplayEditor(){displayDraft={displays:clone(event.config.displays),sponsors:clone(event.config.sponsors)};renderDisplayEditor();}
function renderDisplayEditor(){const fields=event.config.field_sets.flatMap(f=>f.fields);const content=`<h2>Displays & sponsor logos</h2><div class="row between"><h3>Logical displays</h3>${btn('Add display','direct-add-display')}</div>${displayDraft.displays.map((d,i)=>`<div class="display-edit-row"><div class="form-grid">${field('Display name',`<input data-display-input="${i},name" value="${h(d.name)}">`)}${field('Display type',`<select data-display-input="${i},kind">${options(['Pit','Field','Audience'],d.kind)}</select>`)}${field(d.kind==='Field'?'Assigned field':'Default screen',`<select data-display-input="${i},${d.kind==='Field'?'field':'screen'}">${options(d.kind==='Field'?fields:['Rankings','Skills'],d.kind==='Field'?d.field:d.screen)}</select>`)}<div><label class="check"><input type="checkbox" data-display-input="${i},fullscreen" ${d.fullscreen?'checked':''}>Full screen</label>${btn('Remove display',`direct-remove-display:${i}`,'small ghost')}</div></div></div>`).join('')}<div class="row between"><h3>Sponsor logos</h3>${btn('Add logo…','direct-add-logo')}</div>${displayDraft.sponsors.map((s,i)=>`<div class="logo-editor"><img class="sponsor-thumb" src="${imageUrl(s)}" alt="${h(s.name)}"><input data-logo-name="${i}" aria-label="Sponsor name" value="${h(s.name)}"><div class="row">${btn('Replace…',`direct-replace-logo:${i}`,'small')}${btn('↑',`direct-logo-up:${i}`,'small','aria-label="Move sponsor up"')}${btn('↓',`direct-logo-down:${i}`,'small','aria-label="Move sponsor down"')}${btn('Remove',`direct-remove-logo:${i}`,'small ghost')}</div></div>`).join('')||'<p class="muted">No sponsor logos added.</p>'}<div id="display-error" class="notice error" hidden></div><div class="actions">${btn('Cancel','close-modal')}${btn('Apply changes','direct-save-displays','primary')}</div>`;if(!modal.open)dialog(content);else modal.innerHTML=content;modal.classList.add('display-editor');}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.displayInput){const[i,key]=el.dataset.displayInput.split(',');displayDraft.displays[+i][key]=el.type==='checkbox'?el.checked:el.value;if(key==='kind')renderDisplayEditor();}if(el.dataset.logoName!==undefined)displayDraft.sponsors[+el.dataset.logoName].name=el.value;});

document.addEventListener('input',e=>{
 const el=e.target;
 if(wizard)return;
 if((el.dataset.score||el.dataset.dq||el.dataset.noshow)&&tab==='Matches'&&matchDraft?.state!=='Submitted')queueAutosave('submit',{match:matchDraft,draft:true});
 if(el.dataset.bind?.startsWith('awards.'))queueAutosave('awards',{awards:event.awards});
 if(el.id==='announcement')queueAutosave('announcements',{text:el.value});
});
